// The named people of Juniper Bay, Saturday, September 26, 1953 — the Centennial.
//
// HOUSEHOLDS get placed in matching homes (by the home's special tag, building name or family);
// NOTABLES are townsfolk with particular jobs — notables sharing a surname form one household
// unless `own: true`. `home: { name }` can point at a shop (the flat upstairs) or at
// Mrs. Pruitt's Rooms (a lodger's room); if no such home exists, any free house is used.
// job: { building: '<exact building name>', role: '<job role registered by that building>' }
// Everyone also gets generated lines from sim/dialogue.js; `lines` here are their own.
//
// Keep this consistent with city/lore.js and with what the building generators say on their
// plaques and signs (honor rolls, the Pier 3 plaque, shop lore). Cross-references are deliberate:
// people mention each other by name, owe each other, courted each other, taught each other.
// Text uses straight apostrophes inside double-quoted strings and “curly quotes” for quotations.

// look helpers (see people/appearance.js: look.skin, look.hair (colour), look.face, look.hairStyle)
const SK = { fair: '#f3d6bd', light: '#ecc6a4', warm: '#e2b48e', olive: '#d4a07a', tan: '#bf8a62', brown: '#a06a45', dark: '#835236', deep: '#653e28' };
const HC = { black: '#1d1916', dark: '#34231a', brown: '#57391f', auburn: '#7a3a1c', red: '#a34a24', blonde: '#c8a45a', light: '#e0c586', gray: '#8f8a84', white: '#dcd8d0', salt: '#6f6a64' };
const HS = { short: 0, part: 1, bald: 2, long: 3, bob: 4, updo: 5, curly: 6, buzz: 7 };
const FC = { plain: 0, smile: 1, mustache: 2, glasses: 3, glassesMustache: 4, beard: 5, lipstick: 6, lashes: 7, freckles: 8, old: 9, rosy: 10, glassesLipstick: 11 };
const lk = (skin, hair, face, hairStyle, extra = {}) => ({ ...(skin ? { skin } : {}), ...(hair ? { hair, beard: hair } : {}), ...(face !== undefined && face !== null ? { face } : {}), ...(hairStyle !== undefined && hairStyle !== null ? { hairStyle } : {}), ...extra });

